import { queryShortNameTree } from "@/api/safeDanger/report"
import { mapGetters } from 'vuex'
export default {
  name: "workLog",
  props: {
    filesArr: {
      type: Array,
      require: false
    },
    fileTypeText: {
      type: String,
      require: false
    },
    fileType: {
      type: Number,
      require: false
    },
    disabledd: {
      type: Boolean,
      require: false,
      default: false
    }
  },
  computed: {
    ...mapGetters([
      'nickName',
      'companyId',
      'companyCode',
    ]),
    firstCompanys: {
      get(){
        return this.firstCompany
      },
      set(val){
        this.$emit('update:firstCompany', val)
      }
    },
    srcList(){
      return this.filesArrImg1.map(el => el.fileUrl) 
    },
    filesArrImg1(){
      return this.filesArr.filter(el => el.textImages == 1 && el.type == this.fileType)
    },
    filesArrFile1(){
      return this.filesArr.filter(el => el.textImages == 0 && el.type == this.fileType)
    },

    tabName1(){
      if(this.fileTypeText == '整改前'){
        return '隐患图片'
      }
      if(this.fileTypeText == '整改计划'){
        return '整改计划图片'
      }
      if(this.fileTypeText == '整改前'){
        return '隐患图片'
      }
    },
    tabName2(){
      if(this.fileTypeText == '整改前'){
        return '隐患文件'
      }
      if(this.fileTypeText == '整改计划'){
        return '整改计划文件'
      }
      if(this.fileTypeText == '整改后'){
        return '整改文件'
      }
    },

  },
  data() {
